package top.monitorglobal.tv;
import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w1280dp-h720dp-land-hdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class HourlyWeatherTest {
 Context c;private Object field(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 @Before public void setup(){long now=System.currentTimeMillis();org.robolectric.shadows.ShadowSystemClock.advanceBy(java.time.Duration.ofMillis((now/3600000+1)*3600000+60000-now));c=RuntimeEnvironment.getApplication();Prefs.get(c).edit().clear().putInt("rainMode",0).putBoolean("weatherHourly",true).commit();org.robolectric.shadows.ShadowSettings.setCanDrawOverlays(true);Shadows.shadowOf((PowerManager)c.getSystemService(Context.POWER_SERVICE)).setIsInteractive(true);}
 JSONObject weather()throws Exception{long now=System.currentTimeMillis(),start=now/3600000*3600000;return new JSONObject().put("version","tv-weather-v1").put("area","liberdade").put("ok",true).put("loc",new JSONObject().put("lat",RainForecast.LATITUDE).put("lng",RainForecast.LONGITUDE)).put("at",now).put("generatedAt",now).put("expiresAt",Math.min(now+3600000,start+3600000)).put("current",new JSONObject().put("start",start).put("temperature",22).put("feels",23).put("humidity",81).put("wind",12).put("gust",19).put("condition","Cloudy"));}
 void ready(RainMonitor m)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);do{Thread.sleep(5);Shadows.shadowOf(Looper.getMainLooper()).idle();}while(((Boolean)field(m,"busy")||(Boolean)field(m,"weatherBusy"))&&System.nanoTime()<end);assertFalse((Boolean)field(m,"busy"));assertFalse((Boolean)field(m,"weatherBusy"));}
 @Test public void hourlyCardIsIndependentOfRainModeWaitsForPriorityAndDoesNotRepeatEveryMinute()throws Exception{
  AtomicBoolean allowed=new AtomicBoolean(false);AtomicInteger hourlyCalls=new AtomicInteger();RainMonitor m=new RainMonitor(c,allowed::get,()->new JSONObject(),()->{hourlyCalls.incrementAndGet();return weather();});
  try{m.tick();ready(m);assertNull(field(field(m,"overlay"),"current"));assertEquals(0,Prefs.get(c).getLong("weatherLastNotice",0));allowed.set(true);m.tick();View host=(View)field(field(m,"overlay"),"current");assertNotNull(host);assertTrue(Prefs.get(c).getLong("weatherLastNotice",0)>0);assertNull(field(field(m,"overlay"),"drops"));int width=((WindowManager.LayoutParams)host.getLayoutParams()).width;host.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.AT_MOST));host.layout(0,0,width,host.getMeasuredHeight());host.setAlpha(1);((ViewGroup)host).getChildAt(0).setTranslationY(0);assertTrue(host.getHeight()<700);Bitmap b=Bitmap.createBitmap(width,host.getHeight(),Bitmap.Config.ARGB_8888);host.draw(new Canvas(b));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(System.getProperty("java.io.tmpdir"),"monitor-hourly-weather.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();m.hide();m.tick();assertNull(field(field(m,"overlay"),"current"));assertEquals(1,hourlyCalls.get());Prefs.get(c).edit().putLong("weatherLastNotice",System.currentTimeMillis()-3600000).commit();m.tick();assertNotNull(field(field(m,"overlay"),"current"));assertEquals(1,hourlyCalls.get());}finally{m.close();}
 }
 @Test public void manualWorksWithBothAutomaticModesOffAndDoesNotShiftHourlySchedule()throws Exception{Prefs.get(c).edit().putBoolean("weatherHourly",false).commit();AtomicInteger finished=new AtomicInteger();RainMonitor m=new RainMonitor(c,()->true,()->new JSONObject(),this::weather);m.setManualFinished(finished::incrementAndGet);try{m.weatherNow();ready(m);assertNotNull(field(field(m,"overlay"),"current"));assertEquals(0,Prefs.get(c).getLong("weatherLastNotice",0));assertTrue(m.manualPending());Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(14));assertFalse(m.manualPending());assertEquals(1,finished.get());assertNull(field(field(m,"overlay"),"current"));}finally{m.close();}}
 @Test public void missingWeatherFinishesManualWithoutAnEmptyCardOrRainRequest()throws Exception{Prefs.get(c).edit().putBoolean("weatherHourly",false).commit();AtomicInteger rainCalls=new AtomicInteger(),finished=new AtomicInteger();RainMonitor m=new RainMonitor(c,()->true,()->{rainCalls.incrementAndGet();return new JSONObject();},()->new JSONObject());m.setManualFinished(finished::incrementAndGet);try{m.weatherNow();ready(m);Shadows.shadowOf(Looper.getMainLooper()).idle();assertNull(field(field(m,"overlay"),"current"));assertEquals(0,rainCalls.get());assertFalse(m.manualPending());assertEquals(1,finished.get());}finally{m.close();}}
}
